using System.Text;
using System.Xml;
using System.Xml.Linq;

namespace HdrPilot.Core.Games.Scanners.Ea;

/// <summary>
/// Die für HdrPilot nötigen Angaben aus <c>__Installer\installerdata.xml</c> eines EA-Spiels (Wurzel <c>DiPManifest</c>).
/// Aufbau am Zielrechner geprüft an DiPManifest 4.0 („Manifest generated by the EAInstaller-5.08.03.00“).
/// </summary>
internal sealed record EaInstallerData
{
    /// <summary>Werte aus <c>contentIDs/contentID</c> in Dateireihenfolge, ohne leere Einträge.</summary>
    public IReadOnlyList<string> ContentIds { get; init; } = [];

    /// <summary>Anzeigename aus <c>gameTitles/gameTitle</c>: de_DE vor en_US vor dem ersten Eintrag; null, wenn keiner da ist.</summary>
    public string? Title { get; init; }

    /// <summary>Rohwerte aus <c>runtime/launcher/filePath</c>, meist mit Registry-Makro wie <c>[HKEY_LOCAL_MACHINE\…\Install Dir]bf6.exe</c>.</summary>
    public IReadOnlyList<string> LauncherFilePaths { get; init; } = [];

    /// <summary>Rohwert aus <c>uninstall/path</c>: Makro auf den Uninstall-Eintrag des Spiels.</summary>
    public string? UninstallPath { get; init; }
}

internal static class EaInstallerDataParser
{
    private const string RootName = "DiPManifest";

    /// <summary>Bevorzugte Sprachen für den Anzeigenamen, in dieser Reihenfolge.</summary>
    private static readonly string[] PreferredLocales = ["de_DE", "en_US"];

    /// <summary>
    /// Liest die Datei aus Rohbytes; die Kodierung bestimmt der XML-Parser (BOM bzw. XML-Deklaration).
    /// Wirft <see cref="InvalidDataException"/> bei defektem XML, falscher Kodierung oder fremder Wurzel.
    /// </summary>
    public static EaInstallerData Parse(byte[] bytes)
    {
        var root = Load(bytes).Root;
        if (root is null || !Is(root, RootName))
        {
            throw new InvalidDataException($"Wurzelelement ist nicht <{RootName}>, sondern <{root?.Name.LocalName}>.");
        }

        var contentIds = Children(root, "contentIDs")
            .SelectMany(e => Children(e, "contentID"))
            .Select(e => e.Value.Trim())
            .Where(v => v.Length > 0)
            .ToList();

        var titles = Children(root, "gameTitles")
            .SelectMany(e => Children(e, "gameTitle"))
            .Select(e => (Locale: (string?)e.Attribute("locale") ?? string.Empty, Text: e.Value.Trim()))
            .Where(t => t.Text.Length > 0)
            .ToList();

        var launcherPaths = Children(root, "runtime")
            .SelectMany(e => Children(e, "launcher"))
            .SelectMany(e => Children(e, "filePath"))
            .Select(e => e.Value.Trim())
            .Where(v => v.Length > 0)
            .ToList();

        var uninstallPath = Children(root, "uninstall")
            .SelectMany(e => Children(e, "path"))
            .Select(e => e.Value.Trim())
            .FirstOrDefault(v => v.Length > 0);

        return new EaInstallerData
        {
            ContentIds = contentIds,
            Title = PickTitle(titles),
            LauncherFilePaths = launcherPaths,
            UninstallPath = uninstallPath,
        };
    }

    private static XDocument Load(byte[] bytes)
    {
        var settings = new XmlReaderSettings
        {
            DtdProcessing = DtdProcessing.Prohibit,
            IgnoreComments = true,
            IgnoreProcessingInstructions = true,
            CloseInput = true,
        };

        try
        {
            using var reader = XmlReader.Create(new MemoryStream(bytes, writable: false), settings);
            return XDocument.Load(reader);
        }
        catch (XmlException ex)
        {
            throw new InvalidDataException("kein gültiges XML: " + ex.Message, ex);
        }
        catch (DecoderFallbackException ex)
        {
            throw new InvalidDataException("Zeichen passen nicht zur angegebenen Kodierung: " + ex.Message, ex);
        }
    }

    private static string? PickTitle(List<(string Locale, string Text)> titles)
    {
        foreach (var locale in PreferredLocales)
        {
            foreach (var (l, text) in titles)
            {
                if (string.Equals(l.Replace('-', '_'), locale, StringComparison.OrdinalIgnoreCase))
                {
                    return text;
                }
            }
        }

        return titles.Count > 0 ? titles[0].Text : null;
    }

    private static IEnumerable<XElement> Children(XElement parent, string localName) =>
        parent.Elements().Where(e => Is(e, localName));

    private static bool Is(XElement element, string localName) =>
        string.Equals(element.Name.LocalName, localName, StringComparison.OrdinalIgnoreCase);
}
